-- ============================================================================
-- NEW-048 物流车辆调度与运单跟踪管理系统 · 数据库初始化脚本
-- MySQL 8 / utf8mb4 ｜ 执行：mysql -uroot -p123456 < sql/init.sql
-- 生成器：gen/make_sql.py（勿手改，改 schema 后重跑生成器）
-- ============================================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DROP DATABASE IF EXISTS new_048;
CREATE DATABASE new_048 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE new_048;



-- 1 客户档案
CREATE TABLE lg_customer (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  customer_no VARCHAR(30) NOT NULL COMMENT '客户编号',
  name VARCHAR(80) NOT NULL COMMENT '客户名称',
  contact VARCHAR(30) NOT NULL COMMENT '联系人',
  phone VARCHAR(30) NOT NULL COMMENT '联系电话',
  settlement_cycle VARCHAR(30) NOT NULL DEFAULT '月结 30 天' COMMENT '结算周期',
  credit_status VARCHAR(20) NOT NULL DEFAULT 'NORMAL' COMMENT '信用状态 NORMAL/WARN/DISABLED',
  invoice_title VARCHAR(120) DEFAULT NULL COMMENT '开票抬头',
  tax_no VARCHAR(40) DEFAULT NULL COMMENT '税号',
  bank_account VARCHAR(80) DEFAULT NULL COMMENT '开户行与账号',
  total_orders INT NOT NULL DEFAULT 0 COMMENT '累计运单数',
  total_amount DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT '累计费用',
  remark VARCHAR(300) DEFAULT NULL COMMENT '备注',
  deleted TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  create_by VARCHAR(50) DEFAULT NULL COMMENT '创建人',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  version INT NOT NULL DEFAULT 0 COMMENT '乐观锁版本号',
  UNIQUE KEY uk_customer_no (customer_no),
  KEY idx_customer_name (name)
) ENGINE=InnoDB COMMENT='客户档案';

-- 2 客户地址
CREATE TABLE lg_address (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  customer_id BIGINT NOT NULL COMMENT '客户ID',
  customer_name VARCHAR(80) NOT NULL COMMENT '客户名称（冗余便于列表）',
  addr_type VARCHAR(20) NOT NULL COMMENT '地址类型 SHIP/RECEIVE',
  province VARCHAR(30) NOT NULL COMMENT '省',
  city VARCHAR(30) NOT NULL COMMENT '市',
  address VARCHAR(200) NOT NULL COMMENT '详细地址',
  contact VARCHAR(30) NOT NULL COMMENT '现场联系人',
  phone VARCHAR(30) NOT NULL COMMENT '联系电话',
  load_time VARCHAR(40) DEFAULT NULL COMMENT '可装卸时间',
  site_limit VARCHAR(120) DEFAULT NULL COMMENT '场地限制',
  is_default TINYINT NOT NULL DEFAULT 0 COMMENT '是否默认',
  deleted TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_addr_customer (customer_id),
  KEY idx_addr_type (addr_type)
) ENGINE=InnoDB COMMENT='客户常用地址';

-- 3 车辆档案
CREATE TABLE lg_vehicle (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  plate_no VARCHAR(20) NOT NULL COMMENT '车牌号',
  vehicle_type VARCHAR(30) NOT NULL COMMENT '车型 9.6m厢式/13m平板/7.6m冷藏/9.6m高栏/13m厢式',
  load_weight DECIMAL(8,2) NOT NULL COMMENT '核载（吨）',
  volume DECIMAL(8,2) NOT NULL COMMENT '容积（m³）',
  energy_type VARCHAR(20) NOT NULL DEFAULT '柴油' COMMENT '能源类型',
  fleet_name VARCHAR(40) NOT NULL COMMENT '所属车队',
  owner_name VARCHAR(30) DEFAULT NULL COMMENT '车主/挂靠人',
  status VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE' COMMENT '状态 AVAILABLE/RUNNING/MAINT/STOP',
  image VARCHAR(120) DEFAULT NULL COMMENT '车辆照片（本地相对路径）',
  total_trips INT NOT NULL DEFAULT 0 COMMENT '累计任务数',
  mileage DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT '累计里程 km',
  ontime_rate DECIMAL(5,2) NOT NULL DEFAULT 0 COMMENT '近90天准时率 %',
  last_maintain DATE DEFAULT NULL COMMENT '最近保养日期',
  remark VARCHAR(200) DEFAULT NULL COMMENT '备注',
  deleted TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  version INT NOT NULL DEFAULT 0 COMMENT '乐观锁版本号',
  UNIQUE KEY uk_plate_no (plate_no),
  KEY idx_vehicle_status (status),
  KEY idx_vehicle_fleet (fleet_name)
) ENGINE=InnoDB COMMENT='车辆档案';

-- 4 车辆证件
CREATE TABLE lg_vehicle_cert (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  vehicle_id BIGINT NOT NULL COMMENT '车辆ID',
  plate_no VARCHAR(20) NOT NULL COMMENT '车牌号',
  cert_type VARCHAR(30) NOT NULL COMMENT '证件类型 行驶证/年检/商业保险/营运证',
  cert_no VARCHAR(60) NOT NULL COMMENT '证件编号',
  issuer VARCHAR(80) DEFAULT NULL COMMENT '发证机关',
  issue_date DATE NOT NULL COMMENT '生效日期',
  expire_date DATE NOT NULL COMMENT '到期日期',
  file_path VARCHAR(120) DEFAULT NULL COMMENT '证件附件',
  status VARCHAR(20) NOT NULL DEFAULT 'VALID' COMMENT '状态 VALID/WARN/EXPIRED',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_vcert_vehicle (vehicle_id),
  KEY idx_vcert_expire (expire_date)
) ENGINE=InnoDB COMMENT='车辆证件';

-- 5 驾驶员
CREATE TABLE lg_driver (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  driver_no VARCHAR(20) NOT NULL COMMENT '工号',
  name VARCHAR(30) NOT NULL COMMENT '姓名',
  phone VARCHAR(30) NOT NULL COMMENT '联系电话',
  license_type VARCHAR(10) NOT NULL COMMENT '驾驶证类型 A2/B2',
  license_expire DATE NOT NULL COMMENT '驾驶证有效期',
  cert_expire DATE DEFAULT NULL COMMENT '从业资格证有效期',
  fleet_name VARCHAR(40) NOT NULL COMMENT '所属车队',
  avatar VARCHAR(120) DEFAULT NULL COMMENT '头像（本地相对路径）',
  status VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE' COMMENT '状态 AVAILABLE/RUNNING/LEAVE',
  ontime_rate DECIMAL(5,2) NOT NULL DEFAULT 0 COMMENT '近90天准时率 %',
  total_trips INT NOT NULL DEFAULT 0 COMMENT '累计任务数',
  user_id BIGINT DEFAULT NULL COMMENT '关联账号',
  remark VARCHAR(200) DEFAULT NULL COMMENT '备注',
  deleted TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  UNIQUE KEY uk_driver_no (driver_no),
  KEY idx_driver_status (status)
) ENGINE=InnoDB COMMENT='驾驶员档案';

-- 6 驾驶员证件
CREATE TABLE lg_driver_cert (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  driver_id BIGINT NOT NULL COMMENT '驾驶员ID',
  driver_name VARCHAR(30) NOT NULL COMMENT '姓名（冗余）',
  cert_type VARCHAR(30) NOT NULL COMMENT '证件类型 驾驶证/从业资格证/体检记录',
  cert_no VARCHAR(60) NOT NULL COMMENT '证件编号',
  issuer VARCHAR(80) DEFAULT NULL COMMENT '发证机关',
  issue_date DATE NOT NULL COMMENT '生效日期',
  expire_date DATE NOT NULL COMMENT '到期日期',
  file_path VARCHAR(120) DEFAULT NULL COMMENT '证件附件',
  status VARCHAR(20) NOT NULL DEFAULT 'VALID' COMMENT '状态 VALID/WARN/EXPIRED',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_dcert_driver (driver_id)
) ENGINE=InnoDB COMMENT='驾驶员证件';

-- 7 运输需求
CREATE TABLE lg_demand (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  demand_no VARCHAR(30) NOT NULL COMMENT '需求编号',
  customer_id BIGINT NOT NULL COMMENT '客户ID',
  customer_name VARCHAR(80) NOT NULL COMMENT '客户名称（冗余）',
  goods_type VARCHAR(30) NOT NULL COMMENT '货物类型（字典）',
  goods_name VARCHAR(60) NOT NULL COMMENT '货物名称',
  quantity INT NOT NULL DEFAULT 0 COMMENT '件数',
  weight DECIMAL(8,2) NOT NULL COMMENT '重量（吨）',
  volume DECIMAL(8,2) NOT NULL COMMENT '体积（m³）',
  from_address VARCHAR(200) NOT NULL COMMENT '发货地址',
  to_address VARCHAR(200) NOT NULL COMMENT '收货地址',
  expect_load_time DATETIME NOT NULL COMMENT '期望装货时间',
  expect_arrive_time DATETIME NOT NULL COMMENT '要求送达时间',
  status VARCHAR(20) NOT NULL DEFAULT 'SUBMITTED' COMMENT '状态 SUBMITTED/AUDITED/ORDERED/CANCELED',
  audit_by VARCHAR(50) DEFAULT NULL COMMENT '审核人',
  audit_time DATETIME DEFAULT NULL COMMENT '审核时间',
  audit_remark VARCHAR(200) DEFAULT NULL COMMENT '审核意见',
  contact VARCHAR(30) DEFAULT NULL COMMENT '联系人',
  contact_phone VARCHAR(30) DEFAULT NULL COMMENT '联系电话',
  image VARCHAR(120) DEFAULT NULL COMMENT '货物图片',
  remark VARCHAR(300) DEFAULT NULL COMMENT '特殊要求',
  deleted TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  create_by VARCHAR(50) DEFAULT NULL COMMENT '创建人',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  UNIQUE KEY uk_demand_no (demand_no),
  KEY idx_demand_customer (customer_id),
  KEY idx_demand_status (status)
) ENGINE=InnoDB COMMENT='运输需求';

-- 8 货物明细
CREATE TABLE lg_demand_item (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  demand_id BIGINT NOT NULL COMMENT '需求ID',
  goods_name VARCHAR(60) NOT NULL COMMENT '品名',
  spec VARCHAR(60) DEFAULT NULL COMMENT '规格',
  quantity INT NOT NULL DEFAULT 1 COMMENT '数量',
  unit VARCHAR(10) NOT NULL DEFAULT '件' COMMENT '单位',
  weight DECIMAL(8,2) NOT NULL DEFAULT 0 COMMENT '重量（吨）',
  volume DECIMAL(8,2) NOT NULL DEFAULT 0 COMMENT '体积（m³）',
  remark VARCHAR(120) DEFAULT NULL COMMENT '备注',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_item_demand (demand_id)
) ENGINE=InnoDB COMMENT='需求货物明细';

-- 9 运单（核心主数据，对应文档 logistics_dispatch）
CREATE TABLE lg_order (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  order_no VARCHAR(50) NOT NULL COMMENT '运单编号',
  demand_id BIGINT DEFAULT NULL COMMENT '来源需求ID',
  customer_id BIGINT NOT NULL COMMENT '客户ID',
  customer_name VARCHAR(80) NOT NULL COMMENT '发货方（冗余）',
  receiver_name VARCHAR(80) NOT NULL COMMENT '收货方',
  goods_type VARCHAR(30) NOT NULL COMMENT '货物类型（字典）',
  goods_name VARCHAR(60) NOT NULL COMMENT '货物名称',
  quantity INT NOT NULL DEFAULT 0 COMMENT '件数',
  weight DECIMAL(8,2) NOT NULL COMMENT '重量（吨）',
  volume DECIMAL(8,2) NOT NULL COMMENT '体积（m³）',
  from_city VARCHAR(30) NOT NULL COMMENT '始发城市',
  to_city VARCHAR(30) NOT NULL COMMENT '目的城市',
  from_address VARCHAR(200) NOT NULL COMMENT '装货地址',
  to_address VARCHAR(200) NOT NULL COMMENT '卸货地址',
  vehicle_type_req VARCHAR(30) NOT NULL COMMENT '要求车型',
  plan_distance DECIMAL(8,2) NOT NULL DEFAULT 0 COMMENT '计划里程 km',
  plan_hours DECIMAL(6,2) NOT NULL DEFAULT 0 COMMENT '计划时效（小时）',
  plan_load_time DATETIME NOT NULL COMMENT '计划装货时间',
  plan_arrive_time DATETIME NOT NULL COMMENT '预计到达时间',
  require_arrive_time DATETIME NOT NULL COMMENT '要求送达时间',
  actual_arrive_time DATETIME DEFAULT NULL COMMENT '实际到达时间',
  vehicle_id BIGINT DEFAULT NULL COMMENT '车辆ID',
  plate_no VARCHAR(20) DEFAULT NULL COMMENT '车牌号（冗余）',
  driver_id BIGINT DEFAULT NULL COMMENT '驾驶员ID',
  driver_name VARCHAR(30) DEFAULT NULL COMMENT '驾驶员姓名（冗余）',
  status VARCHAR(20) NOT NULL DEFAULT 'CREATED' COMMENT '状态 CREATED/DISPATCHED/LOADED/SHIPPING/ARRIVED/SIGNED/FEE_CHECK/DONE/EXCEPTION/CANCELED',
  exception_flag VARCHAR(20) NOT NULL DEFAULT 'NORMAL' COMMENT '异常标记 NORMAL/DELAY/DAMAGE/REJECT/OTHER',
  fee_total DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT '费用合计',
  receivable DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT '应收合计',
  cargo_image VARCHAR(120) DEFAULT NULL COMMENT '货物图片',
  remark VARCHAR(300) DEFAULT NULL COMMENT '特殊注意事项',
  deleted TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  create_by VARCHAR(50) DEFAULT NULL COMMENT '创建人',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  version INT NOT NULL DEFAULT 0 COMMENT '乐观锁版本号',
  UNIQUE KEY uk_order_no (order_no),
  KEY idx_order_status (status),
  KEY idx_order_customer (customer_id),
  KEY idx_order_create (create_time)
) ENGINE=InnoDB COMMENT='运单主档';

-- 10 调度任务（对应文档 logistics_dispatch_order）
CREATE TABLE lg_dispatch (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  dispatch_no VARCHAR(30) NOT NULL COMMENT '调度单号',
  order_id BIGINT NOT NULL COMMENT '运单ID',
  order_no VARCHAR(50) NOT NULL COMMENT '运单编号（冗余）',
  customer_name VARCHAR(80) NOT NULL COMMENT '客户（冗余）',
  from_city VARCHAR(30) NOT NULL COMMENT '始发城市',
  to_city VARCHAR(30) NOT NULL COMMENT '目的城市',
  goods_desc VARCHAR(80) DEFAULT NULL COMMENT '货物与载重描述',
  vehicle_id BIGINT DEFAULT NULL COMMENT '车辆ID',
  plate_no VARCHAR(20) DEFAULT NULL COMMENT '车牌号',
  driver_id BIGINT DEFAULT NULL COMMENT '驾驶员ID',
  driver_name VARCHAR(30) DEFAULT NULL COMMENT '驾驶员',
  plan_load_time DATETIME DEFAULT NULL COMMENT '计划装货时间',
  plan_arrive_time DATETIME DEFAULT NULL COMMENT '预计到达时间',
  status VARCHAR(20) NOT NULL DEFAULT 'TODO' COMMENT '状态 TODO/PROCESSING/DONE/EXCEPTION/CANCELED',
  origin_vehicle VARCHAR(20) DEFAULT NULL COMMENT '原车辆（改派留痕）',
  origin_driver VARCHAR(30) DEFAULT NULL COMMENT '原驾驶员（改派留痕）',
  change_reason VARCHAR(200) DEFAULT NULL COMMENT '变更原因',
  change_time DATETIME DEFAULT NULL COMMENT '变更时间',
  dispatcher VARCHAR(50) DEFAULT NULL COMMENT '调度员',
  score_id BIGINT DEFAULT NULL COMMENT '配车评分ID',
  deadline DATETIME DEFAULT NULL COMMENT '处理时限',
  remark VARCHAR(200) DEFAULT NULL COMMENT '进度说明',
  deleted TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  UNIQUE KEY uk_dispatch_no (dispatch_no),
  KEY idx_dispatch_order (order_id),
  KEY idx_dispatch_status (status)
) ENGINE=InnoDB COMMENT='车辆调度任务';

-- 11 装车记录
CREATE TABLE lg_load (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  load_no VARCHAR(30) NOT NULL COMMENT '装车单号',
  order_id BIGINT NOT NULL COMMENT '运单ID',
  order_no VARCHAR(50) NOT NULL COMMENT '运单编号（冗余）',
  plan_weight DECIMAL(8,2) NOT NULL COMMENT '计划重量',
  plan_volume DECIMAL(8,2) NOT NULL COMMENT '计划体积',
  real_weight DECIMAL(8,2) NOT NULL COMMENT '实际重量',
  real_volume DECIMAL(8,2) NOT NULL COMMENT '实际体积',
  diff_rate DECIMAL(6,2) NOT NULL DEFAULT 0 COMMENT '差异率 %',
  diff_flag VARCHAR(20) NOT NULL DEFAULT 'NORMAL' COMMENT '差异判定 NORMAL/OVER',
  load_time DATETIME NOT NULL COMMENT '装车时间',
  site_contact VARCHAR(60) DEFAULT NULL COMMENT '现场联系人',
  cargo_images VARCHAR(300) DEFAULT NULL COMMENT '货物照片（多张，逗号分隔）',
  status VARCHAR(20) NOT NULL DEFAULT 'CONFIRMED' COMMENT '状态 PENDING/CONFIRMED/REJECTED',
  confirm_by VARCHAR(50) DEFAULT NULL COMMENT '确认人',
  confirm_time DATETIME DEFAULT NULL COMMENT '确认时间',
  remark VARCHAR(200) DEFAULT NULL COMMENT '备注',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_load_order (order_id)
) ENGINE=InnoDB COMMENT='装车记录';

-- 12 运输节点
CREATE TABLE lg_node (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  node_no VARCHAR(30) NOT NULL COMMENT '节点编号',
  order_id BIGINT NOT NULL COMMENT '运单ID',
  order_no VARCHAR(50) NOT NULL COMMENT '运单编号（冗余）',
  node_type VARCHAR(20) NOT NULL COMMENT '节点类型 LOAD/DEPART/TRANSIT/ARRIVE/UNLOAD/SIGN',
  node_name VARCHAR(30) NOT NULL COMMENT '节点名称',
  place VARCHAR(120) NOT NULL COMMENT '地点文字',
  node_time DATETIME NOT NULL COMMENT '发生时间',
  description VARCHAR(300) DEFAULT NULL COMMENT '说明',
  images VARCHAR(300) DEFAULT NULL COMMENT '节点图片',
  reporter VARCHAR(50) DEFAULT NULL COMMENT '上报人',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_node_order (order_id),
  KEY idx_node_time (node_time)
) ENGINE=InnoDB COMMENT='运输节点';

-- 13 异常事件
CREATE TABLE lg_exception (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  exception_no VARCHAR(30) NOT NULL COMMENT '异常编号',
  order_id BIGINT NOT NULL COMMENT '运单ID',
  order_no VARCHAR(50) NOT NULL COMMENT '运单编号（冗余）',
  type VARCHAR(30) NOT NULL COMMENT '异常类型 堵车延误/车辆故障/货损货差/拒收/地址变更/延误',
  level VARCHAR(20) NOT NULL DEFAULT 'MID' COMMENT '程度 LOW/MID/HIGH/SEVERE',
  description VARCHAR(300) NOT NULL COMMENT '简要描述',
  owner_name VARCHAR(30) DEFAULT NULL COMMENT '责任人',
  deadline DATETIME DEFAULT NULL COMMENT '处理时限',
  process_note VARCHAR(500) DEFAULT NULL COMMENT '处理过程',
  customer_note VARCHAR(300) DEFAULT NULL COMMENT '客户沟通记录',
  images VARCHAR(300) DEFAULT NULL COMMENT '现场照片',
  status VARCHAR(20) NOT NULL DEFAULT 'OPEN' COMMENT '状态 OPEN/PROCESSING/PENDING_AUDIT/CLOSED',
  audit_by VARCHAR(50) DEFAULT NULL COMMENT '审核人',
  audit_time DATETIME DEFAULT NULL COMMENT '审核时间',
  audit_note VARCHAR(200) DEFAULT NULL COMMENT '审核意见',
  reporter VARCHAR(50) DEFAULT NULL COMMENT '登记人',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  UNIQUE KEY uk_exception_no (exception_no),
  KEY idx_exc_order (order_id),
  KEY idx_exc_status (status)
) ENGINE=InnoDB COMMENT='异常事件';

-- 14 沟通记录
CREATE TABLE lg_comm (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  exception_id BIGINT NOT NULL COMMENT '异常ID',
  exception_no VARCHAR(30) NOT NULL COMMENT '异常编号（冗余）',
  way VARCHAR(20) NOT NULL COMMENT '沟通方式 电话/微信/现场/邮件',
  content VARCHAR(400) NOT NULL COMMENT '沟通内容',
  operator VARCHAR(30) NOT NULL COMMENT '沟通人',
  comm_time DATETIME NOT NULL COMMENT '沟通时间',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_comm_exc (exception_id)
) ENGINE=InnoDB COMMENT='异常沟通记录';

-- 15 签收
CREATE TABLE lg_sign (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  order_id BIGINT NOT NULL COMMENT '运单ID',
  order_no VARCHAR(50) NOT NULL COMMENT '运单编号（冗余）',
  plan_qty INT NOT NULL DEFAULT 0 COMMENT '应收数量',
  real_qty INT NOT NULL DEFAULT 0 COMMENT '实收数量',
  diff_note VARCHAR(200) DEFAULT NULL COMMENT '差异说明',
  signer VARCHAR(30) NOT NULL COMMENT '签收人',
  sign_phone VARCHAR(30) DEFAULT NULL COMMENT '签收人电话',
  sign_time DATETIME NOT NULL COMMENT '签收时间',
  images VARCHAR(300) DEFAULT NULL COMMENT '签收凭证',
  status VARCHAR(20) NOT NULL DEFAULT 'SIGNED' COMMENT '状态 SIGNED/DISPUTE',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_sign_order (order_id)
) ENGINE=InnoDB COMMENT='签收记录';

-- 16 回单
CREATE TABLE lg_receipt (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  receipt_no VARCHAR(30) NOT NULL COMMENT '回单编号',
  order_id BIGINT NOT NULL COMMENT '运单ID',
  order_no VARCHAR(50) NOT NULL COMMENT '运单编号（冗余）',
  uploader VARCHAR(30) NOT NULL COMMENT '上传人',
  file_count INT NOT NULL DEFAULT 0 COMMENT '凭证张数',
  images VARCHAR(400) DEFAULT NULL COMMENT '凭证图片',
  status VARCHAR(20) NOT NULL DEFAULT 'PENDING' COMMENT '状态 PENDING/REJECTED/CHECKED/ARCHIVED',
  reject_reason VARCHAR(200) DEFAULT NULL COMMENT '退回原因',
  paper_status VARCHAR(20) NOT NULL DEFAULT 'NONE' COMMENT '纸质回单 NONE/MAILED/RECEIVED/ARCHIVED',
  archive_location VARCHAR(80) DEFAULT NULL COMMENT '存放位置',
  check_by VARCHAR(50) DEFAULT NULL COMMENT '复核人',
  check_time DATETIME DEFAULT NULL COMMENT '复核时间',
  upload_time DATETIME NOT NULL COMMENT '上传时间',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  UNIQUE KEY uk_receipt_no (receipt_no),
  KEY idx_receipt_order (order_id),
  KEY idx_receipt_status (status)
) ENGINE=InnoDB COMMENT='回单与签收凭证';

-- 17 费用类型
CREATE TABLE lg_fee_type (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  type_code VARCHAR(30) NOT NULL COMMENT '编码',
  type_name VARCHAR(30) NOT NULL COMMENT '名称',
  direction VARCHAR(10) NOT NULL COMMENT '方向 RECV应收/PAY应付',
  default_rate DECIMAL(10,2) DEFAULT NULL COMMENT '默认单价（元/公里或元/吨）',
  status TINYINT NOT NULL DEFAULT 1 COMMENT '状态 1启用 0停用',
  remark VARCHAR(120) DEFAULT NULL COMMENT '说明',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  UNIQUE KEY uk_fee_type (type_code)
) ENGINE=InnoDB COMMENT='费用类型';

-- 18 费用记录
CREATE TABLE lg_fee (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  fee_no VARCHAR(30) NOT NULL COMMENT '费用单号',
  order_id BIGINT NOT NULL COMMENT '运单ID',
  order_no VARCHAR(50) NOT NULL COMMENT '运单编号（冗余）',
  fee_type VARCHAR(30) NOT NULL COMMENT '费用类型',
  direction VARCHAR(10) NOT NULL COMMENT '方向 RECV/PAY',
  amount DECIMAL(12,2) NOT NULL COMMENT '金额（负数表示赔付）',
  voucher VARCHAR(200) DEFAULT NULL COMMENT '凭证图片',
  status VARCHAR(20) NOT NULL DEFAULT 'PENDING' COMMENT '状态 PENDING/CHECKED/REJECTED',
  submitter VARCHAR(30) NOT NULL COMMENT '提交人',
  submit_time DATETIME NOT NULL COMMENT '提交时间',
  audit_by VARCHAR(50) DEFAULT NULL COMMENT '审核人',
  audit_time DATETIME DEFAULT NULL COMMENT '审核时间',
  audit_note VARCHAR(200) DEFAULT NULL COMMENT '审核意见',
  remark VARCHAR(200) DEFAULT NULL COMMENT '备注',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  UNIQUE KEY uk_fee_no (fee_no),
  KEY idx_fee_order (order_id),
  KEY idx_fee_status (status)
) ENGINE=InnoDB COMMENT='费用记录';

-- 19 客户账单
CREATE TABLE lg_bill (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  bill_no VARCHAR(30) NOT NULL COMMENT '账单编号',
  customer_id BIGINT NOT NULL COMMENT '客户ID',
  customer_name VARCHAR(80) NOT NULL COMMENT '客户名称（冗余）',
  period VARCHAR(20) NOT NULL COMMENT '账期 yyyy-MM',
  order_count INT NOT NULL DEFAULT 0 COMMENT '运单数',
  total_amount DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT '账单金额',
  paid_amount DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT '已收金额',
  unpaid_amount DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT '未收金额',
  status VARCHAR(20) NOT NULL DEFAULT 'UNPAID' COMMENT '状态 UNPAID/PART/PAID/CHECKED',
  bill_date DATE NOT NULL COMMENT '出账日期',
  remark VARCHAR(200) DEFAULT NULL COMMENT '备注',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  UNIQUE KEY uk_bill_no (bill_no),
  KEY idx_bill_customer (customer_id),
  KEY idx_bill_period (period)
) ENGINE=InnoDB COMMENT='客户账单';

-- 20 收付款
CREATE TABLE lg_payment (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  payment_no VARCHAR(30) NOT NULL COMMENT '流水号',
  bill_id BIGINT DEFAULT NULL COMMENT '账单ID',
  ref_no VARCHAR(30) DEFAULT NULL COMMENT '关联单号',
  target_name VARCHAR(80) NOT NULL COMMENT '往来单位',
  direction VARCHAR(10) NOT NULL COMMENT '方向 RECV/PAY',
  amount DECIMAL(12,2) NOT NULL COMMENT '金额',
  pay_method VARCHAR(30) NOT NULL COMMENT '方式 银行转账/承兑汇票/现金/对公转账',
  status VARCHAR(20) NOT NULL DEFAULT 'REGISTERED' COMMENT '状态 REGISTERED/PENDING/CHECKED/PAID',
  pay_date DATE NOT NULL COMMENT '日期',
  operator VARCHAR(30) NOT NULL COMMENT '登记人',
  remark VARCHAR(200) DEFAULT NULL COMMENT '备注',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  UNIQUE KEY uk_payment_no (payment_no)
) ENGINE=InnoDB COMMENT='线下收付款登记';

-- 21 服务评价
CREATE TABLE lg_review (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  review_no VARCHAR(30) NOT NULL COMMENT '评价编号',
  order_id BIGINT NOT NULL COMMENT '运单ID',
  order_no VARCHAR(50) NOT NULL COMMENT '运单编号（冗余）',
  customer_name VARCHAR(80) NOT NULL COMMENT '客户（冗余）',
  score TINYINT NOT NULL COMMENT '评分 1-5',
  content VARCHAR(400) DEFAULT NULL COMMENT '评价内容',
  tags VARCHAR(100) DEFAULT NULL COMMENT '标签',
  status VARCHAR(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态 NORMAL/ABNORMAL',
  review_time DATETIME NOT NULL COMMENT '评价时间',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  UNIQUE KEY uk_review_no (review_no),
  KEY idx_review_order (order_id)
) ENGINE=InnoDB COMMENT='服务评价';

-- 22 配车规则（创新点：容量与时间窗联合配车）
CREATE TABLE lg_rule (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  version VARCHAR(10) NOT NULL COMMENT '版本号 v1/v2/v3',
  weights VARCHAR(300) NOT NULL COMMENT '各维度权重 JSON：load/volume/type/deadhead/timewin/ontime',
  threshold_recommend INT NOT NULL DEFAULT 85 COMMENT '推荐阈值',
  threshold_backup INT NOT NULL DEFAULT 70 COMMENT '备选阈值',
  max_deadhead_km INT NOT NULL DEFAULT 120 COMMENT '空驶上限 km',
  min_gap_minutes INT NOT NULL DEFAULT 60 COMMENT '任务最小间隔分钟',
  load_limit_rate INT NOT NULL DEFAULT 100 COMMENT '核载利用率上限 %',
  volume_limit_rate INT NOT NULL DEFAULT 95 COMMENT '容积利用率上限 %',
  status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' COMMENT '状态 ACTIVE/ARCHIVED',
  effect_time DATETIME NOT NULL COMMENT '生效时间',
  create_by VARCHAR(50) DEFAULT NULL COMMENT '修改人',
  remark VARCHAR(200) DEFAULT NULL COMMENT '变更说明',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  UNIQUE KEY uk_rule_version (version)
) ENGINE=InnoDB COMMENT='配车规则版本';

-- 23 配车评分（计算留痕）
CREATE TABLE lg_score (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  order_id BIGINT NOT NULL COMMENT '运单ID',
  order_no VARCHAR(50) NOT NULL COMMENT '运单编号（冗余）',
  rule_id BIGINT NOT NULL COMMENT '规则ID',
  rule_version VARCHAR(10) NOT NULL COMMENT '规则版本',
  input_snapshot VARCHAR(600) NOT NULL COMMENT '输入快照 JSON',
  total_score INT NOT NULL COMMENT '总分',
  result_level VARCHAR(20) NOT NULL COMMENT '结果等级 RECOMMEND/BACKUP/REJECT',
  vehicle_id BIGINT NOT NULL COMMENT '推荐车辆ID',
  plate_no VARCHAR(20) NOT NULL COMMENT '车牌号',
  driver_id BIGINT DEFAULT NULL COMMENT '推荐驾驶员ID',
  driver_name VARCHAR(30) DEFAULT NULL COMMENT '驾驶员',
  main_factors VARCHAR(400) DEFAULT NULL COMMENT '主要影响因素',
  unmet_conditions VARCHAR(300) DEFAULT NULL COMMENT '未满足条件',
  improvements VARCHAR(300) DEFAULT NULL COMMENT '可改进项',
  manual_flag TINYINT NOT NULL DEFAULT 0 COMMENT '是否人工修正',
  manual_vehicle VARCHAR(20) DEFAULT NULL COMMENT '人工修正车辆',
  manual_reason VARCHAR(300) DEFAULT NULL COMMENT '修正原因',
  manual_by VARCHAR(50) DEFAULT NULL COMMENT '修正人',
  manual_time DATETIME DEFAULT NULL COMMENT '修正时间',
  gen_time DATETIME NOT NULL COMMENT '计算时间',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_score_order (order_id)
) ENGINE=InnoDB COMMENT='配车评分与计算快照';

-- 24 评分明细
CREATE TABLE lg_score_item (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  score_id BIGINT NOT NULL COMMENT '评分ID',
  dimension VARCHAR(30) NOT NULL COMMENT '评分维度',
  basis VARCHAR(200) NOT NULL COMMENT '计算依据',
  full_score INT NOT NULL COMMENT '单项满分',
  weight INT NOT NULL COMMENT '权重 %',
  weighted_score DECIMAL(6,2) NOT NULL COMMENT '加权得分',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_score_item (score_id)
) ENGINE=InnoDB COMMENT='配车评分明细';

-- 25 组织
CREATE TABLE sys_org (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  parent_id BIGINT NOT NULL DEFAULT 0 COMMENT '上级',
  org_name VARCHAR(60) NOT NULL COMMENT '组织名称',
  org_type VARCHAR(20) NOT NULL DEFAULT 'COMPANY' COMMENT '类型 COMPANY/FLEET/DEPT',
  leader VARCHAR(30) DEFAULT NULL COMMENT '负责人',
  sort INT NOT NULL DEFAULT 0 COMMENT '排序',
  status TINYINT NOT NULL DEFAULT 1 COMMENT '状态',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间'
) ENGINE=InnoDB COMMENT='组织与车队';

-- 26 用户
CREATE TABLE sys_user (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  username VARCHAR(40) NOT NULL COMMENT '登录名',
  password VARCHAR(100) NOT NULL COMMENT 'BCrypt 密码',
  real_name VARCHAR(30) NOT NULL COMMENT '姓名',
  phone VARCHAR(30) DEFAULT NULL COMMENT '手机号',
  email VARCHAR(80) DEFAULT NULL COMMENT '邮箱',
  org_id BIGINT DEFAULT NULL COMMENT '组织ID',
  org_name VARCHAR(60) DEFAULT NULL COMMENT '组织名称（冗余）',
  avatar VARCHAR(120) DEFAULT NULL COMMENT '头像',
  gender VARCHAR(4) DEFAULT NULL COMMENT '性别',
  status TINYINT NOT NULL DEFAULT 1 COMMENT '状态 1启用 0停用',
  login_fail_count INT NOT NULL DEFAULT 0 COMMENT '连续失败次数',
  lock_until DATETIME DEFAULT NULL COMMENT '锁定至',
  last_login DATETIME DEFAULT NULL COMMENT '最近登录',
  deleted TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  UNIQUE KEY uk_username (username)
) ENGINE=InnoDB COMMENT='系统用户';

-- 27 角色
CREATE TABLE sys_role (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  role_code VARCHAR(40) NOT NULL COMMENT '角色编码',
  role_name VARCHAR(40) NOT NULL COMMENT '角色名称',
  data_scope VARCHAR(20) NOT NULL DEFAULT 'self' COMMENT '数据范围 all/dept/self/org',
  remark VARCHAR(200) DEFAULT NULL COMMENT '说明',
  status TINYINT NOT NULL DEFAULT 1 COMMENT '状态',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  UNIQUE KEY uk_role_code (role_code)
) ENGINE=InnoDB COMMENT='角色';

-- 28 菜单
CREATE TABLE sys_menu (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  parent_id BIGINT NOT NULL DEFAULT 0 COMMENT '上级菜单',
  menu_name VARCHAR(40) NOT NULL COMMENT '菜单名称',
  menu_type VARCHAR(20) NOT NULL DEFAULT 'menu' COMMENT '类型 catalog/menu/button',
  path VARCHAR(120) DEFAULT NULL COMMENT '路由路径',
  perm VARCHAR(80) DEFAULT NULL COMMENT '权限标识',
  icon VARCHAR(30) DEFAULT NULL COMMENT '图标',
  sort INT NOT NULL DEFAULT 0 COMMENT '排序',
  visible TINYINT NOT NULL DEFAULT 1 COMMENT '是否可见',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间'
) ENGINE=InnoDB COMMENT='菜单';

-- 29 角色菜单
CREATE TABLE sys_role_menu (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  role_id BIGINT NOT NULL COMMENT '角色ID',
  menu_id BIGINT NOT NULL COMMENT '菜单ID',
  UNIQUE KEY uk_role_menu (role_id, menu_id)
) ENGINE=InnoDB COMMENT='角色菜单授权';

-- 30 用户角色
CREATE TABLE sys_user_role (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  user_id BIGINT NOT NULL COMMENT '用户ID',
  role_id BIGINT NOT NULL COMMENT '角色ID',
  UNIQUE KEY uk_user_role (user_id, role_id)
) ENGINE=InnoDB COMMENT='用户角色';

-- 31 字典
CREATE TABLE sys_dict (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  dict_type VARCHAR(40) NOT NULL COMMENT '字典类型',
  dict_label VARCHAR(40) NOT NULL COMMENT '标签',
  dict_value VARCHAR(40) NOT NULL COMMENT '值',
  sort INT NOT NULL DEFAULT 0 COMMENT '排序',
  status TINYINT NOT NULL DEFAULT 1 COMMENT '状态',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_dict_type (dict_type)
) ENGINE=InnoDB COMMENT='数据字典';

-- 32 站内消息
CREATE TABLE sys_message (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  msg_type VARCHAR(30) NOT NULL COMMENT '类型 待审批/即将超时/已退回/待验收',
  title VARCHAR(200) NOT NULL COMMENT '标题',
  biz_no VARCHAR(50) DEFAULT NULL COMMENT '业务编号',
  biz_path VARCHAR(120) DEFAULT NULL COMMENT '详情跳转地址',
  receiver VARCHAR(40) DEFAULT NULL COMMENT '接收人（空为广播）',
  is_read TINYINT NOT NULL DEFAULT 0 COMMENT '是否已读',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_msg_receiver (receiver)
) ENGINE=InnoDB COMMENT='站内消息';

-- 33 操作日志
CREATE TABLE sys_log (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  username VARCHAR(40) NOT NULL COMMENT '操作人',
  action VARCHAR(60) NOT NULL COMMENT '动作',
  target VARCHAR(80) DEFAULT NULL COMMENT '对象',
  detail VARCHAR(400) DEFAULT NULL COMMENT '详情',
  ip VARCHAR(40) DEFAULT NULL COMMENT 'IP',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_log_time (create_time)
) ENGINE=InnoDB COMMENT='操作日志';



































-- ----------------------------------------------------------------------------
-- 冗余字段回填（列表页直接取，避免每次 JOIN）
-- ----------------------------------------------------------------------------
UPDATE lg_order o SET o.receivable = (SELECT COALESCE(SUM(f.amount),0) FROM lg_fee f
  WHERE f.order_id = o.id AND f.direction = 'RECV' AND f.status = 'CHECKED');
UPDATE lg_order o SET o.fee_total = (SELECT COALESCE(SUM(ABS(f.amount)),0) FROM lg_fee f WHERE f.order_id = o.id);
UPDATE lg_customer c SET c.total_orders = (SELECT COUNT(*) FROM lg_order o WHERE o.customer_id = c.id AND o.deleted = 0);
UPDATE lg_customer c SET c.total_amount = (SELECT COALESCE(SUM(o.receivable),0) FROM lg_order o WHERE o.customer_id = c.id);
UPDATE lg_vehicle v SET v.total_trips = (SELECT COUNT(*) FROM lg_dispatch d WHERE d.vehicle_id = v.id);
UPDATE lg_driver d SET d.total_trips = (SELECT COUNT(*) FROM lg_dispatch t WHERE t.driver_id = d.id);

SET FOREIGN_KEY_CHECKS = 1;
